    private const val PREFS_NAME = "vizor_native_strings"
    private const val LANGUAGE_KEY = "language"

    /** The app language tag Dart last sent; English until it sends one. */
    fun language(context: Context): String =
        context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
            ?.getString(LANGUAGE_KEY, null) ?: "en"

    fun setLanguage(context: Context, tag: String) {
        context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
            .edit()
            .putString(LANGUAGE_KEY, tag)
            .apply()
    }

    fun text(context: Context, key: NativeString, vararg args: Pair<String, String>): String =
        text(language(context), key, *args)

    /**
     * [key] in [language], or English when that language has no
     * translation. `{name}` placeholders take their value from [args].
     */
    fun text(language: String, key: NativeString, vararg args: Pair<String, String>): String {
        val template = when (language) {
            "ko" -> ko[key]
            "zh" -> zh[key]
            else -> null
        } ?: en(key)
        return args.fold(template) { message, (name, value) -> message.replace("{$name}", value) }
    }

